<?php		include('..\..\..\GestionVoiture\Controller\controllerPersonne.php');		$ajout= new controllerPersonne();				session_start();				if(isset($_GET['b1']))		{								$ajout->updatePersonne($_SESSION['id'],$_GET['z2'],$_GET['z3'],$_GET['z4']);				session_destroy();				header('Location:showPersonne.php');		}		else		{						$id=$_GET['id'];			$nom=$_GET['nom'];			$prenom=$_GET['prenom'];			$adresse=$_GET['adresse'];			$_SESSION['id']=$id;					}?><html>	<head><title> Modifier Personne </title></head>	<body>		<form method ="GET" action ="updatePersonne.php">		<table>				 <tr><td>Nom </td><td> <input type="text" name="z2" value="<?php echo $nom; ?>"></td></tr>		 <tr><td>Prenom </td><td><input type="text" name="z3" value="<?php echo $prenom; ?>"></td></tr>		 <tr><td>Adresse </td><td><input type="text" name="z4" value="<?php echo $adresse; ?>"></td></tr>		 <tr><td><input type="submit" name="b1" value="Modifier"></td></tr>		 </table>		</form>	</body></html>